CREATE VIEW [CE].[vwQuote]
AS
SELECT
	[quoteid],
	[quotenumber],
	[msdyn_quotenumber],
	[name],
	quo.[description],
	COALESCE([apuk_campaignyear], IIF(MONTH(QUO.[createdon]) >= 10, YEAR(QUO.[createdon]) + 1, YEAR(QUO.[createdon]))) AS [apuk_campaignyear],
	[campaignid],
	CON.Rics_contactno AS Contact_No,
	--con.apuk_contactnumber AS Contact_No,
	QUO.[createdon],
	QUO.createdbyID,
	QUO.[createdby],
	QUO.[modifiedon],
	QUO.[modifiedby],
	QUO.[ownerid],
	QUO.apuk_paymentmethod,
	QUO.apuk_paymentmethod_description,
	--CON.[apuk_paymentmethod],
	--paymethod.[LocalizedLabel] AS [apuk_paymentmethod_description],

	[msdyn_salesquotationstatus],
	[msdyn_salesquotationstatus_description],
	[msdyn_ordertype],
	[apuk_invoicesalesorder],
	[apuk_quoteaccepted],
	[apuk_paymentreceived],
	[apuk_casedrs],
	QUO.[accountid],
	[apuk_enrolmentid],
	[apuk_regulatedschemeid],
	QUO.[apuk_ricsrecordid],
	[opportunityid],
	[msdyn_invoicecustomer],
	QUO.[transactioncurrencyid],
	[msdyn_isocurrencycode],
	CURR.isocurrencycode AS Transaction_Currency_Code,
	[apuk_productsubscriptionid],
	[apuk_subscriptionid],
	[apuk_subscriptionproducttype],
	[apuk_subscriptionproducttype_description],
	[customerid],
	[msdyn_invoicecustomerid],
	[totallineitemamount],
	[totallineitemamount_base],
	[totallineitemdiscountamount],
	[totallineitemdiscountamount_base],
	[totalamountlessfreight],
	[totalamountlessfreight_base],
	[totaldiscountamount],
	[totaldiscountamount_base],
	[totalamount],
	[totalamount_base],
	[totaltax],
	[totaltax_base],
	[apuk_lionheartdonation],
	[apuk_lionheartdonation_base],
	QUO.[exchangerate],
	[apuk_totalprofessionalfees],
	[apuk_totalprofessionalfees_base],
	[apuk_purchaseordernumber],
	[closedon],
	[apuk_subscriptionstartdate],
	[apuk_subscriptionenddate],
	[requestdeliveryby],
	[msdyn_quotelinestartdate],
	[msdyn_quotelineenddate],
	QUO.statecode AS statecode,
	QUO.[StateCode_Description] AS StateCode_Description,
	QUO.statuscode AS [statuscode],
	QUO.[StatusCode_Description] AS [StatusCode_Description],
	/*
	IIF(is_credited = 1, 9, QUO.statecode) AS statecode,
	IIF(is_credited = 1, 'Credited', QUO.[StateCode_Description]) AS StateCode_Description,
	IIF(is_credited = 1, 9, QUO.statuscode) AS [statuscode],
	IIF(is_credited = 1, 'Credited', QUO.[StatusCode_Description]) AS [StatusCode_Description],
	*/
	NULL AS is_credited,
	QUO.[statecode] AS statecode_original,
	QUO.[StateCode_Description] AS StateCode_Description_original,
	QUO.[statuscode] AS statuscode_original,
	QUO.[StatusCode_Description] AS StatusCode_Description_original,
	[apuk_billto],
	[apuk_directdebitfees],
	[apuk_directdebitfees_base],
	--ISNULL(totalamount, 0.0) + ISNULL(apuk_lionheartdonation, 0.0) + ISNULL(apuk_directdebitfees, 0.0) AS [Total_Incl_Charges], --Removed 05/09/23, it's just emulating apuk_totalprofessionalfees
	--ISNULL(totalamount_base, 0.0) + ISNULL(apuk_lionheartdonation_base, 0.0) + ISNULL(apuk_directdebitfees_base, 0.0) AS [Total_Incl_Charges_Base], --As above
	apuk_totalprofessionalfees AS [Total_Incl_Charges],
	apuk_totalprofessionalfees_base AS [Total_Incl_Charges_Base],
	apuk_corppaymentref,
	quo.[shipto_fax]
FROM [synapse_ce].[vwQuote] QUO
LEFT JOIN synapse_ce.vwContact CON ON QUO.customerid = CON.ContactId
--LEFT JOIN synapse_ce.contact con ON QUO.customerid = con.Id
--LEFT JOIN synapse_ce.GlobalOptionSetMetadata paymethod
--		ON con.[apuk_paymentmethod] = paymethod.[Option]
--			AND paymethod.[OptionSetName] = 'apuk_paymentmethod'
--			AND paymethod.[EntityName] = 'contact'
LEFT JOIN [synapse_ce].[TransactionCurrency] CURR
	ON QUO.transactioncurrencyid = CURR.transactioncurrencyid
